type Account = { userId: string; token: string };

function makeAccount(): Account {
  return { userId: "id-42", token: "tok-abc" };
}

// Use the whole thing...
const account = makeAccount();
console.log(account.userId, account.token);

// ...or unpack just what you need.
const { token } = makeAccount();
console.log("just the token:", token);

// The shape, with a stand-in for the real context.
type FakeRequest = { post: (url: string) => Promise<string> };

async function createThing(req: FakeRequest, name: string): Promise<string> {
  return `${await req.post("/things")}:${name}`;
}

const fakeReq: FakeRequest = { post: async (url) => `POSTed ${url}` };
console.log(await createThing(fakeReq, "widget"));
console.log("the caller owns the context; the helper just borrows it");

import { writeProjectFile } from "../_shared/deno-helpers.ts";

// A plain module: exported functions and one exported type.

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week7/generated/api-helpers.ts", `// Week 7, Day 5 — the duplication, removed.
//
// Day 4's beforeAll created a user and fetched a token. Every API spec you write
// from here needs the same six lines. This file is those lines, once.
//
// Note the filename: NOT .spec.ts. It defines behaviour and calls no test(), so
// the runner never collects it — the same rule as a page object (week3/day3_2).
import { expect, type APIRequestContext } from "@playwright/test";

export const BASE_URL = "https://demoqa.com";

/** What a caller actually needs back. Two values, so return an object. */
export type Account = {
  userName: string;
  password: string;
  userId: string;
  token: string;
};

/**
 * Create a user and authorise them, in one call.
 *
 * \`request\` is passed IN rather than imported: an APIRequestContext belongs to
 * the running test, so a helper cannot conjure one. Every Playwright helper that
 * touches the network takes it as its first parameter.
 */
export async function createAccount(
  request: APIRequestContext,
  prefix = "w7",
): Promise<Account> {
  // Unique per call, because this is a shared public sandbox.
  const userName = \`\${prefix}_\${Date.now()}_\${Math.floor(Math.random() * 1000)}\`;
  const password = "Passw0rd@123";

  const created = await request.post(\`\${BASE_URL}/Account/v1/User\`, {
    data: { userName, password },
  });
  // An assertion in a helper is fine when it is about the helper's own contract:
  // if this fails, no test using it can be meaningful. It is NOT a test's
  // assertion — see week6/day2_2 for the same rule in a page object.
  expect(created.status(), \`createAccount: expected 201, got \${created.status()}\`).toBe(201);
  const userId = (await created.json()).userID as string;

  const tokenResponse = await request.post(\`\${BASE_URL}/Account/v1/GenerateToken\`, {
    data: { userName, password },
  });
  const token = (await tokenResponse.json()).token as string;
  expect(token, "createAccount: no token returned").toBeTruthy();

  return { userName, password, userId, token };
}

/** The header every authorised call needs. One place to change it. */
export function authHeader(account: Account): { Authorization: string } {
  return { Authorization: \`Bearer \${account.token}\` };
}

/** Tidy up. Safe to call twice: a second delete just answers 401. */
export async function deleteAccount(
  request: APIRequestContext,
  account: Account,
): Promise<void> {
  await request.delete(\`\${BASE_URL}/Account/v1/User/\${account.userId}\`, {
    headers: authHeader(account),
  });
}
`);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week7/generated/day5-shared-helper.spec.ts", `// Week 7, Day 5 — the same journey as Day 4, through the helper.
//
// Compare the beforeAll here with day4-chaining.spec.ts: nine lines became one.
//
// Written by a cell in week7/day5_2.ipynb. Run it yourself:
//   npx playwright test week7/generated/day5-shared-helper.spec.ts
import { test, expect } from "@playwright/test";
import { BASE_URL, authHeader, createAccount, deleteAccount, type Account } from "./api-helpers";

test.describe("Using the helper", () => {
  test.describe.configure({ mode: "serial" });

  let account: Account;

  test.beforeAll(async ({ request }) => {
    // One line. The user exists and is authorised.
    account = await createAccount(request, "w7d5");
  });

  test("Step 1 — the helper handed back everything we need", async () => {
    expect(account.userId).toBeTruthy();
    expect(account.token).toBeTruthy();
    expect(account.userName).toContain("w7d5");
  });

  test("Step 2 — authHeader() removes the last repeated line", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/Account/v1/User/\${account.userId}\`, {
      headers: authHeader(account),
    });

    expect(response.status()).toBe(200);
    expect((await response.json()).username).toBe(account.userName);
  });

  test("Step 3 — a real test, with no setup noise in it", async ({ request }) => {
    const response = await request.post(\`\${BASE_URL}/BookStore/v1/Books\`, {
      headers: authHeader(account),
      data: { userId: account.userId, collectionOfIsbns: [{ isbn: "9781449325862" }] },
    });

    expect(response.status()).toBe(201);
  });

  test("Step 4 — adding the same book twice is refused", async ({ request }) => {
    // A fresh account, so this test proves the behaviour on its own rather than
    // depending on whatever Step 3 left behind. A test that needs another test to
    // have run first is a test that fails mysteriously later.
    const solo = await createAccount(request, "w7d5dup");
    const body = {
      userId: solo.userId,
      collectionOfIsbns: [{ isbn: "9781449325862" }],
    };

    const first = await request.post(\`\${BASE_URL}/BookStore/v1/Books\`, {
      headers: authHeader(solo),
      data: body,
    });
    expect(first.status()).toBe(201);

    const second = await request.post(\`\${BASE_URL}/BookStore/v1/Books\`, {
      headers: authHeader(solo),
      data: body,
    });
    expect(second.status()).toBe(400);
    expect((await second.json()).code).toBe("1210");

    await deleteAccount(request, solo);
  });

  test.afterAll(async ({ request }) => {
    await deleteAccount(request, account);
  });
});
`);

// Expected: 4 passed. Compare this beforeAll with day4's.
await runSpec("week7/generated/day5-shared-helper.spec.ts");

Nine lines became one:

```ts
test.beforeAll(async ({ request }) => {
  account = await createAccount(request, "w7d5");
});
```

Step 4 of that run is worth a second look: it creates its **own** account rather than relying on
Step 3 having added a book first. A test that needs another test to have run is a test that fails
mysteriously later - and it was written the fragile way first, which is how the bug was found.

