await writeProjectFile("week7/generated/day5-data-driven.spec.ts", `// Week 7, Day 5 — five scenarios, one test.
//
// The session sets this as homework: rather than five near-identical tests, put
// the differences in data and loop. Each row still reports as its own test, so a
// failure names the case.
//
// Written by a cell in week7/day5_2.ipynb. Run it yourself:
//   npx playwright test week7/generated/day5-data-driven.spec.ts
import { test, expect } from "@playwright/test";
import { BASE_URL, authHeader, createAccount, deleteAccount, type Account } from "./api-helpers";
import cases from "./day5-register-cases.json";

test.describe("Registering a user — the whole truth table", () => {
  // Users the valid case creates, so we can clean up afterwards.
  const created: Account[] = [];

  // The loop is OUTSIDE test(), so Playwright sees five tests at collection
  // time. Put it inside and you get one test that stops at the first failure.
  for (const testCase of cases.cases) {
    test(\`\${testCase.expectedStatus} — \${testCase.name}\`, async ({ request }) => {
      // "AUTO" means "give me a unique name"; a blank string is a real test input.
      const userName =
        testCase.userName === "AUTO" ? \`w7dd_\${Date.now()}_\${Math.floor(Math.random() * 1000)}\` : testCase.userName;

      const response = await request.post(\`\${BASE_URL}/Account/v1/User\`, {
        data: { userName, password: testCase.password },
      });

      expect(response.status()).toBe(testCase.expectedStatus);

      const body = await response.json();

      if (testCase.expectedCode) {
        // A failure: the API explains itself with a code and a sentence.
        expect(body.code).toBe(testCase.expectedCode);
        expect(body.message).toContain(testCase.messageContains);
      } else {
        // The success row: a real user, so remember it and delete it later.
        expect(body.userID).toBeTruthy();
        const tokenResponse = await request.post(\`\${BASE_URL}/Account/v1/GenerateToken\`, {
          data: { userName, password: testCase.password },
        });
        created.push({
          userName,
          password: testCase.password,
          userId: body.userID,
          token: (await tokenResponse.json()).token,
        });
      }
    });
  }

  test.afterAll(async ({ request }) => {
    for (const account of created) await deleteAccount(request, account);
  });
});

test.describe("The case that does not fit the table", () => {
  // "Registering a name that already exists" needs a name that already exists -
  // a prerequisite, not a data row. Not everything belongs in the JSON.
  test("406 — a duplicate username is refused", async ({ request }) => {
    const account = await createAccount(request, "w7ddup");

    const again = await request.post(\`\${BASE_URL}/Account/v1/User\`, {
      data: { userName: account.userName, password: account.password },
    });

    // 406 Not Acceptable for a duplicate USER — while a duplicate BOOK is 400.
    // Same API, two different choices. Read the response; never assume.
    expect(again.status()).toBe(406);
    const body = await again.json();
    expect(body.code).toBe("1204");
    expect(body.message).toContain("User exists!");

    await deleteAccount(request, account);
  });
});
`);

// Expected: 6 passed - five from the table, one that could not fit in it.
await runSpec("week7/generated/day5-data-driven.spec.ts");

# Week 7, Day 5.3 - The next step: fixtures

`createAccount()` is a function you must remember to call. A fixture is the same function that
calls itself - and cleans up after itself.

## The same helper, as a fixture

```ts
// api-fixtures.ts
import { test as base } from "@playwright/test";
import { createAccount, deleteAccount, type Account } from "./api-helpers";

export const test = base.extend<{ account: Account }>({
  account: async ({ request }, use) => {
    const created = await createAccount(request);
    await use(created);                       // the test body runs here
    await deleteAccount(request, created);    // teardown - even if it failed
  },
});
export { expect } from "@playwright/test";
```

A spec then asks for what it needs and nothing more:

```ts
test("a new account owns no books", async ({ request, account }) => {
  const response = await request.get(`${BASE_URL}/Account/v1/User/${account.userId}`, {
    headers: authHeader(account),
  });
  expect((await response.json()).books).toEqual([]);
});
```

// Why laziness matters, counted. A fixture only runs for tests that ask.
const suite = [
  { test: "books list is not empty", needsAccount: false },
  { test: "one book by ISBN", needsAccount: false },
  { test: "unknown ISBN is 400", needsAccount: false },
  { test: "a new account owns no books", needsAccount: true },
  { test: "adding a book works", needsAccount: true },
];

const withBeforeAll = suite.length;                          // hook runs for all
const withFixture = suite.filter((t) => t.needsAccount).length;

console.log("accounts created with beforeAll:", withBeforeAll);
console.log("accounts created with a fixture:", withFixture);
console.log("wasted round trips saved       :", withBeforeAll - withFixture);
